style.css:
@-moz-document url-prefix("http") {
/* CORPO GERAL */
  body {
    background-color: #1e1e2f !important; /* fundo escuro chique */
    color: #f0f0f0 !important; /* texto claro bonitão */
    font-family: 'Arial', sans-serif !important;
  }

  /* LINKS */
  a {
    color: #ff79c6 !important; /* rosa cyberpunk */
  }

  a:hover {
    color: #8be9fd !important; /* azul neon no hover */
  }

  /* ESCONDER COISAS CHATA */
  header, footer, .ads, .banner, [id*="ad"], [class*="ad"] {
    display: none !important;
  }
}
